const Context = createContext({ language: "vi" as Language, setLanguage: (_: Language) => {}, t: (key: MessageKey, values?: TranslationValues): string => {
  let message = vi[key];
  for (const [name, value] of Object.entries(values ?? {})) message = message.replaceAll(`{{${name}}}`, String(value)).replaceAll(`{${name}}`, String(value));
  return message;
} });
export function LanguageProvider({ children }: { children: ReactNode }) {
  const [language, setLanguage] = useState<Language>(() => { try { return localStorage.getItem("mindcanvas:language") === "en" ? "en" : "vi"; } catch { return "vi"; } });
  const [selectedTheme, setSelectedTheme] = useState<Theme>(() => { try { const saved = localStorage.getItem("mindcanvas:theme"); return isTheme(saved) ? saved : DEFAULT_THEME; } catch { return DEFAULT_THEME; } });
  const [previewTheme, setPreviewTheme] = useState<Theme | null>(null);
  const theme = previewTheme ?? selectedTheme;
  const setTheme = useCallback((next: Theme) => { setSelectedTheme(next); setPreviewTheme(null); }, []);
  const preview = useCallback((next: Theme) => setPreviewTheme(next), []);
  const clearPreview = useCallback(() => setPreviewTheme(null), []);
  useEffect(() => { document.documentElement.lang = language; try { localStorage.setItem("mindcanvas:language", language); } catch {} }, [language]);
  useEffect(() => {
    document.documentElement.dataset.theme = theme;
    const [gradientStart, gradientEnd] = themeGradient(theme);
    document.documentElement.style.setProperty("--theme-gradient-start", gradientStart);
    document.documentElement.style.setProperty("--theme-gradient-end", gradientEnd);
    document.querySelector<HTMLMetaElement>('meta[name="theme-color"]')?.setAttribute("content", themeBrowserColor(theme));
  }, [theme]);
  useEffect(() => { try { localStorage.setItem("mindcanvas:theme", selectedTheme); } catch {} }, [selectedTheme]);
  return <Context.Provider value={{ language, setLanguage, t: (key, values) => {
    let message = (language === "vi" ? vi : en)[key];
    for (const [name, value] of Object.entries(values ?? {})) message = message.replaceAll(`{{${name}}}`, String(value)).replaceAll(`{${name}}`, String(value));
    return message;
  } }}><ThemeContext.Provider value={{ theme, selectedTheme, previewTheme, setTheme, preview, clearPreview }}>{children}</ThemeContext.Provider></Context.Provider>;
}
export const useLanguage = () => useContext(Context);
export const useTheme = () => useContext(ThemeContext);
